import {fields,presets,readTheme,validateTheme,STORAGE_KEY,contrast} from './theme.js';
const $=s=>document.querySelector(s);
let draft=readTheme(), comparing=false;
const iframe=$('#preview');
const status=message=>$('#status').textContent=message;
let revision=0;
function preview(){
 const theme=comparing?{version:1,...presets[0]}:draft;
 document.documentElement.style.setProperty('--preview-background',theme.colors.background);
 iframe.contentWindow?.postMessage({type:'htwkr-theme-preview',theme,revision:++revision},location.origin);
}
function update(){
 $('#name').value=draft.name;
 const brightness=Math.round((draft.pageBrightness??1)*100);
 $('#page-brightness').value=brightness;$('#brightness-value').value=`${brightness}%`;
 $('#page-brightness').setAttribute('aria-valuetext',`${brightness}%`);
 for(const [key] of fields){$(`#picker-${key}`).value=draft.colors[key];$(`#hex-${key}`).value=draft.colors[key];$(`#hex-${key}`).setCustomValidity('');}
 document.querySelectorAll('.preset').forEach((button,i)=>button.setAttribute('aria-pressed',JSON.stringify(draft.colors)===JSON.stringify(presets[i].colors)));
 const match=presets.find(p=>JSON.stringify(p.colors)===JSON.stringify(draft.colors));
 $('#description').textContent=match?.description||'自定义方案：改一个颜色，右侧马上预览。';
 const ratios=[['主要文字',contrast(draft.colors.text,draft.colors.background)],['辅助文字',contrast(draft.colors.muted,draft.colors.background)],['链接',contrast(draft.colors.accent,draft.colors.background)],['按钮文字',contrast(draft.colors.onSurface,draft.colors.surface)]];
 $('#contrast').textContent=ratios.map(([label,r])=>`${label} ${r.toFixed(1)}:1${r<4.5?'（建议加大反差）':' ✓'}`).join(' · ');
 $('#preview-label').textContent=comparing?'正在查看原版黑色':draft.name;
 $('#compare').setAttribute('aria-pressed',comparing);$('#compare').textContent=comparing?'返回当前方案':'对比原版';preview();
}
for(const [index,preset] of presets.entries()){
 const button=document.createElement('button');button.className='preset';button.innerHTML=`<span>${preset.name}</span><span class="swatches" aria-hidden="true">${['background','surface','muted','accent'].map(k=>`<i style="background:${preset.colors[k]}"></i>`).join('')}</span>`;
 button.onclick=()=>{draft={version:1,name:preset.name,colors:{...preset.colors},pageBrightness:draft.pageBrightness??1};comparing=false;update();status('正在预览，点击保存后应用到网站。');};$('#presets').append(button);
}
for(const [key,label,hint] of fields){
 const row=document.createElement('div');row.className='color-row';row.innerHTML=`<label for="picker-${key}">${label}<small>${hint}</small></label><input type="color" id="picker-${key}" aria-label="${label}"><input class="hex" type="text" id="hex-${key}" aria-label="${label}十六进制" pattern="#[0-9A-Fa-f]{6}" maxlength="7" spellcheck="false">`;
 row.querySelectorAll('input').forEach(input=>input.addEventListener('input',()=>{if(!/^#[\da-f]{6}$/i.test(input.value)){input.setCustomValidity('请输入 #RRGGBB');return;}input.setCustomValidity('');draft.colors[key]=input.value.toLowerCase();comparing=false;update();status('有未保存的配色修改。');}));$('#colors').append(row);
}
function setBrightness(percent){draft.pageBrightness=percent/100;comparing=false;update();status('书页亮度已预览，保存后会和配色一起保留。');}
$('#page-brightness').oninput=e=>setBrightness(Number(e.target.value));
$('#brightness-suggest').onclick=()=>setBrightness(115);
$('#brightness-reset').onclick=()=>setBrightness(100);
$('#name').oninput=e=>{draft.name=e.target.value;$('#preview-label').textContent=draft.name;status('方案名称尚未保存。');};
$('#compare').onclick=()=>{comparing=!comparing;update();};
$('#desktop').onclick=()=>device(false);$('#mobile').onclick=()=>device(true);
function device(mobile){iframe.classList.toggle('mobile',mobile);$('#mobile').setAttribute('aria-pressed',mobile);$('#desktop').setAttribute('aria-pressed',!mobile);}
$('#save').onclick=()=>{try{draft=validateTheme(draft);localStorage.setItem(STORAGE_KEY,JSON.stringify(draft));comparing=false;update();status('已保存。当前浏览器、当前网址的书本会使用这套配色。');}catch(e){status(`保存失败：${e.message} 请导出配置备份。`);}};
$('#restore').onclick=()=>{draft=readTheme();comparing=false;update();status('已恢复上次保存的方案；没有存档时恢复原版黑色。');};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(validateTheme(draft),null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='portfolio-theme.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status('已导出当前方案，可在其他浏览器导入。');};
$('#import-button').onclick=()=>$('#import').click();
$('#import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>20000)throw new Error('配置文件过大。');const next=validateTheme(JSON.parse(await file.text()));draft=next;comparing=false;update();status('导入成功。确认效果后点击保存。');}catch(err){status(`导入失败：${err.message} 当前配色未改变。`);}e.target.value='';};
window.addEventListener('message',e=>{
 if(e.origin!==location.origin||e.source!==iframe.contentWindow)return;
 if(e.data?.type==='htwkr-theme-ready'){
  iframe.style.visibility='hidden';$('.preview-surround').setAttribute('aria-busy','true');preview();
 }
 if(e.data?.type==='htwkr-theme-applied'&&e.data.revision===revision){
  iframe.style.visibility='visible';$('.preview-surround').setAttribute('aria-busy','false');
 }
});
iframe.addEventListener('load',preview);update();
